const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const acreFC = gaul.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'Brazil'),
      ee.Filter.eq('ADM1_NAME', 'Acre')
    ));
    const acreCount = await acreFC.size().getInfo();
    if (!acreCount || acreCount === 0) {
      console.log('Region not found: Acre, Brazil');
      console.log('C1');
      return;
    }
    const acre = ee.Feature(acreFC.first()).geometry();

    const julyStart = '2005-07-01';
    const julyEnd = '2005-08-01';
    const sepStart = '2005-09-01';
    const sepEnd = '2005-10-01';

    const DOY_JULY_LATE = {min: 201, max: 212};  // 20–31 July 2005
    const DOY_SEP_LATE = {min: 263, max: 273};   // 20–30 September 2005

    // 2. Data Acquisition & Check with fallback
    async function getMonthlyImage(start, end) {
      let used = 'MODIS/061/MCD64A1';
      let col = ee.ImageCollection(used).filterDate(start, end).select('BurnDate');
      let size = await col.size().getInfo();
      if (!size || size === 0) {
        used = 'MODIS/006/MCD64A1';
        col = ee.ImageCollection(used).filterDate(start, end).select('BurnDate');
        size = await col.size().getInfo();
      }
      return {size, used, img: col.first()};
    }

    const julyData = await getMonthlyImage(julyStart, julyEnd);
    const sepData = await getMonthlyImage(sepStart, sepEnd);

    console.log(`July images: ${julyData.size} (${julyData.used})`);
    console.log(`September images: ${sepData.size} (${sepData.used})`);

    if (!julyData.size || !sepData.size) {
      console.log('C1');
      return;
    }

    // 3. Processing: mask by late-window DOY and compute counts/area
    function maskByDoy(img, range) {
      const bd = img.select('BurnDate');
      const mask = bd.gte(range.min).and(bd.lte(range.max));
      return bd.updateMask(mask).rename('BurnDate');
    }

    async function burnStats(img, geom, range) {
      const maskedBD = maskByDoy(img, range);
      const count = await maskedBD.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e13
      }).get('BurnDate').getInfo();

      const areaKm2 = await ee.Image.pixelArea()
        .updateMask(maskedBD.mask())
        .divide(1e6)  // m² to km²
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: geom,
          scale: 1000,
          maxPixels: 1e13
        }).get('area').getInfo();

      return {count, areaKm2};
    }

    const julStats = await burnStats(julyData.img, acre, DOY_JULY_LATE);
    const sepStats = await burnStats(sepData.img, acre, DOY_SEP_LATE);

    // 4. Validation & Final Answer logic
    const invalid = (v) => v === null || v === undefined || (typeof v === 'number' && !isFinite(v));
    if (invalid(julStats.count) || invalid(julStats.areaKm2) ||
        invalid(sepStats.count) || invalid(sepStats.areaKm2)) {
      console.log('C3');
      return;
    }

    const julArea = Math.max(0, julStats.areaKm2 || 0);
    const sepArea = Math.max(0, sepStats.areaKm2 || 0);
    const diff = sepArea - julArea;

    console.log(`July late burned px: ${Math.round(julStats.count || 0)}`);
    console.log(`July late burned area (km²): ${julArea.toFixed(2)}`);
    console.log(`Sep late burned px: ${Math.round(sepStats.count || 0)}`);
    console.log(`Sep late burned area (km²): ${sepArea.toFixed(2)}`);
    console.log(`Increase (Sep - Jul) km²: ${diff.toFixed(2)}`);

    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
